107	  public void setTemplateEntriesForChild(CapacitySchedulerConfiguration conf,
108	                                         String childQueuePath,
109	                                         boolean isLeaf) {
110	    if (childQueuePath.equals(ROOT)) {
111	      return;
112	    }
113	
114	    ConfigurationProperties configurationProperties =
115	        conf.getConfigurationProperties();
116	
117	    // Get all properties that are explicitly set
118	    Set<String> alreadySetProps = configurationProperties
119	        .getPropertiesWithPrefix(CapacitySchedulerConfiguration
120	            .getQueuePrefix(childQueuePath)).keySet();
121	
122	    // Check template properties only set for leaf or parent queues
123	    Map<String, String> queueTypeSpecificTemplates = parentOnlyProperties;
124	    if (isLeaf) {
125	      queueTypeSpecificTemplates = leafOnlyProperties;
126	    }
127	
128	    for (Map.Entry<String, String> entry :
129	        queueTypeSpecificTemplates.entrySet()) {
130	      // Do not overwrite explicitly configured properties
131	      if (alreadySetProps.contains(entry.getKey())) {
132	        continue;
133	      }
134	      conf.set(CapacitySchedulerConfiguration.getQueuePrefix(
135	          childQueuePath) + entry.getKey(), entry.getValue());
136	    }
137	
138	    for (Map.Entry<String, String> entry : templateProperties.entrySet()) {
139	      // Do not overwrite explicitly configured properties or properties set
140	      // by queue type specific templates (parent-template and leaf-template)
141	      if (alreadySetProps.contains(entry.getKey())
142	          || queueTypeSpecificTemplates.containsKey(entry.getKey())) {
143	        continue;
