150	  /**
151	   * Store the template configuration properties. Explicit templates always take
152	   * precedence over wildcard values. An example template precedence
153	   * hierarchy for root.a ParentQueue from highest to lowest:
154	   * yarn.scheduler.capacity.root.a.auto-queue-creation-v2.template.capacity
155	   * yarn.scheduler.capacity.root.*.auto-queue-creation-v2.template.capacity
156	   */
157	  private void setTemplateConfigEntries(CapacitySchedulerConfiguration configuration,
158	                                        String queuePath) {
159	    ConfigurationProperties configurationProperties =
160	        configuration.getConfigurationProperties();
161	
162	    List<String> queuePathParts = new ArrayList<>(Arrays.asList(
163	        queuePath.split("\\.")));
164	
165	    if (queuePathParts.size() <= 1 && !queuePath.equals(ROOT)) {
166	      // This is an invalid queue path
167	      return;
168	    }
169	    int queuePathMaxIndex = queuePathParts.size() - 1;
170	
171	    // start with the most explicit format (without wildcard)
172	    int wildcardLevel = 0;
173	    // root can not be wildcarded
174	    // MAX_WILDCARD_LEVEL will be configurable in the future
175	    int supportedWildcardLevel = Math.min(queuePathMaxIndex - 1,
176	        MAX_WILDCARD_LEVEL);
177	    // Allow root to have template properties
178	    if (queuePath.equals(ROOT)) {
179	      supportedWildcardLevel = 0;
180	    }
181	
182	    // Collect all template entries
183	    while (wildcardLevel <= supportedWildcardLevel) {
184	      String templateQueuePath = String.join(".", queuePathParts);
185	      // Get all configuration entries with
186	      // yarn.scheduler.capacity.<queuePath> prefix
187	      Map<String, String> queueProps = configurationProperties
188	          .getPropertiesWithPrefix(getQueuePrefix(templateQueuePath));
189	
190	      // Store template, parent-template and leaf-template properties
191	      for (Map.Entry<String, String> entry : queueProps.entrySet()) {
192	        storeConfiguredTemplates(entry.getKey(), entry.getValue());
193	      }
194	
195	      // Replace a queue part with a wildcard based on the wildcard level
196	      // eg. root.a -> root.*
197	      int queuePartToWildcard = queuePathMaxIndex - wildcardLevel;
198	      queuePathParts.set(queuePartToWildcard, WILDCARD_QUEUE);
199	
200	      ++wildcardLevel;
201	    }
202	  }
