204	  private void storeConfiguredTemplates(
205	      String templateKey, String templateValue) {
206	    String prefix = "";
207	    Map<String, String> properties = templateProperties;
208	
209	    if (templateKey.startsWith(AUTO_QUEUE_TEMPLATE_PREFIX)) {
210	      prefix = AUTO_QUEUE_TEMPLATE_PREFIX;
211	    } else if (templateKey.startsWith(AUTO_QUEUE_LEAF_TEMPLATE_PREFIX)) {
212	      prefix = AUTO_QUEUE_LEAF_TEMPLATE_PREFIX;
213	      properties = leafOnlyProperties;
214	    } else if (templateKey.startsWith(
215	        AUTO_QUEUE_PARENT_TEMPLATE_PREFIX)) {
216	      prefix = AUTO_QUEUE_PARENT_TEMPLATE_PREFIX;
217	      properties = parentOnlyProperties;
218	    }
219	
220	    if (!prefix.isEmpty()) {
221	      // Trim template prefix from key
222	      String key = templateKey.substring(prefix.length());
223	      // If an entry is already present, it had a higher precedence
224	      properties.putIfAbsent(key, templateValue);
225	    }
226	  }
