56	      CapacitySchedulerQueueManager queueManager, String fullPath)
57	      throws YarnException {
58	    //Normalizing the root of the path
59	    ArrayList<String> parts = new ArrayList<>();
60	    Collections.addAll(parts, fullPath.split("\\."));
61	
62	    //the first element of the path is the path root
63	    String pathRoot = parts.get(0);
64	    CSQueue pathRootQueue = queueManager.getQueue(pathRoot);
65	    if (pathRootQueue == null) {
66	      if (queueManager.isAmbiguous(pathRoot)) {
67	        throw new YarnException("Path root '" + pathRoot +
68	            "' is ambiguous. Path '" + fullPath + "' is invalid");
69	      } else {
70	        throw new YarnException("Path root '" + pathRoot +
71	            "' does not exist. Path '" + fullPath + "' is invalid");
72	      }
73	    }
74	
75	    //Normalizing the root
76	    parts.set(0, pathRootQueue.getQueuePath());
77	    return String.join(DOT, parts);
78	  }
